  void display() { System.out.println(str); }
}
class Multilevel {
  public static void main(String args[]) {
    D d = new D();
    d.display();
  }
}

SUBJECT: Software Engineering | UNIT: 2 | TOPIC: SUPER KEYWORD IN JAVA

Exercise - 5 Aim: 5a) Write a JAVA program give example for "super" keyword.
Program:
class A {
  int i = 10;
  A() { System.out.println("Constructor in A class"); }
  void view() {
    System.out.println("View Method in A class");
    System.out.println("i value : " + i);
  }
}
class B extends A {
  int j;
  B(int j) {
    super();
    this.j = j;
  }
  void display() {
    super.view();
    System.out.println("display Method in B class");
    System.out.println("i value is " + super.i);
    System.out.println("j value is " + j);
  }
}
class Super1 {
  public static void main(String args[]) {
    B b = new B(10);
    b.display();
  }
}

SUBJECT: Software Engineering | UNIT: 2 | TOPIC: ABSTRACT CLASSES IN JAVA

Aim: 4(c) Write a JAVA program for abstract class to find areas of different shapes
import java.util.Scanner;
abstract class CalcArea {
  abstract void findTriangle(double b, double h);
  abstract void findRectangle(double l, double b);
  abstract void findSquare(double s);
  abstract void findCircle(double r);
}
class FindArea extends CalcArea {
  void findTriangle(double b, double h) { double area = (b * h) / 2; System.out.println("Area of Triangle: " + area); }
  void findRectangle(double l, double b) { double area = l * b; System.out.println("Area of Rectangle: " + area); }
  void findSquare(double s) { double area = s * s; System.out.println("Area of Square: " + area); }
  void findCircle(double r) { double area = 3.14 * r * r; System.out.println("Area of Circle: " + area); }
}
class Area {
  public static void main(String args[]) {
    FindArea area = new FindArea();
    area.findTriangle(10, 5);
    area.findRectangle(10, 20);
    area.findSquare(5);
    area.findCircle(7);
  }
}

