Aim: 5c) Write a JAVA program that implements Run time polymorphism
class A { public void display() { System.out.println("Inside A's display method"); } }
class B extends A { public void display() { System.out.println("Inside B's display method"); } }
class C extends B { public void display() { System.out.println("Inside C's display method"); } }
class Ex8a {
  public static void main(String args[]) {
    A a1 = new A();
    B b1 = new B();
    C c1 = new C();
    A ref;
    ref = a1; ref.display();
    ref = b1; ref.display();
    ref = c1; ref.display();
  }
}

